# compute_revenue.py

def compute_revenue(prices, quantities):
    """Compute total revenue as sum(price * quantity). Expects iterables of equal length."""
    if len(prices) != len(quantities):
        raise ValueError("prices and quantities must have same length")
    return sum(p * q for p, q in zip(prices, quantities))


if __name__ == "__main__":
    # example usage
    prices = [10.0, 20.5, 5.25]
    quantities = [3, 2, 10]
    print("Total revenue:", compute_revenue(prices, quantities))

