# calculate_revenue.py
import sys
import json

def calculate_revenue(items):
    """Calculate total revenue from a list of items.

    Each item is expected to be a dict with numeric keys 'price' and 'quantity'.
    Returns total revenue as a float.
    """
    total = 0.0
    for it in items:
        try:
            price = float(it.get("price", 0))
        except Exception:
            price = 0.0
        try:
            qty = float(it.get("quantity", 0))
        except Exception:
            qty = 0.0
        total += price * qty
    return total

if __name__ == "__main__":
    # Example usage: provide a JSON array of items via stdin, e.g.:
    #   echo '[{"price": 10, "quantity": 2}, {"price": 5.5, "quantity": 3}]' | python calculate_revenue.py
    try:
        data = json.load(sys.stdin)
        if not isinstance(data, list):
            raise ValueError
    except Exception:
        # Fallback example data
        data = [{"price": 10.0, "quantity": 2}, {"price": 5.5, "quantity": 3}]
    total = calculate_revenue(data)
    # Print as simple number (standard revenue case)
    print(total)

